    static int MsiReplayCaseCount;
    static void ReplayCase(string id,Action<object> body,string product="MS-1T41",string expected="ClawA1M",int firmware=0x167)
    {
        MsiReplayIoPorts.Reset();try{ManualCase(id,backend=>{MsiReplayCaseCount++;ApplyManual(backend);MsiReplayIoPorts.Fire();Check(MsiManualIoPorts.Rows.Count(r=>r.Stage=="write")==4,"Initial queued callback with no edge cannot repeat a manual submission");MsiManualIoPorts.Rows.Clear();MsiReplayIoPorts.Arms.Clear();body(backend);},product,expected,firmware);}finally{MsiReplayIoPorts.Enabled=false;}
    }
    static object ReplayProfile(object backend,string name)
    {
        var profile=Invoke(backend,"CloneHcPowerProfile",Get(backend,"hcProfileTemplate")!)!;Set(profile,"Name",name);return profile;
    }
    static Delegate ProfileDelegates(string eventName)
    {
        var factory=Hc!.GetType("HandheldCompanion.Managers.ManagerFactory",true)!;var manager=factory.GetField("powerProfileManager",All)!.GetValue(null)!;return(Delegate)manager.GetType().GetField(eventName,All)!.GetValue(manager)!;
    }
    static void EmitApplied(object backend,string name)
    {
        var profile=ReplayProfile(backend,name);var source=Enum.Parse(Hc!.GetType("HandheldCompanion.UpdateSource",true)!,"QuickProfilesPage");ProfileDelegates("Applied").DynamicInvoke(profile,source);
    }
    static void ReplayWritesOnSta(object backend)
    {
        var owner=(Thread)Get(backend,"staThread")!;var writes=MsiManualIoPorts.Rows.Where(r=>r.Stage=="write").ToArray();Check(writes.Length>=2,"Actual replay must execute original table writers");Check(writes.All(r=>r.Thread==owner.ManagedThreadId),"Every replay write must execute on the original owned STA, never the timer callback worker");Check(MsiReplayIoPorts.Fires.All(r=>r.IsThreadPool&&r.Apartment=="MTA"&&r.Thread!=owner.ManagedThreadId),"Replay probe must execute the original callback on an actual independent ThreadPool MTA");
    }
    static void ReplayWaitsForOriginalSta(object backend,Action onSta,Action afterCallbackQueued)
    {
        using var entered=new ManualResetEventSlim();using var release=new ManualResetEventSlim();var blocking=Task.Run(()=>Sta(backend,()=>{entered.Set();if(!release.Wait(TimeSpan.FromSeconds(5)))throw new InvalidOperationException("OWNED_STA_BLOCK_TIMEOUT");onSta();},"replay-owned-admission-block"));Task? callback=null;
        try
        {
            Check(entered.Wait(TimeSpan.FromSeconds(3)),"Original STA blocker must own a live original dispatched work item");callback=MsiReplayIoPorts.FireAsync();
            Check(SpinWait.SpinUntil(()=>MsiReplayIoPorts.LastCallbackThread is Thread t&&(t.ThreadState&System.Threading.ThreadState.WaitSleepJoin)!=0,TimeSpan.FromSeconds(3)),"Actual original ThreadPool callback must wait for the already-owned STA before the competing change");afterCallbackQueued();
        }
        finally{release.Set();if(!blocking.Wait(TimeSpan.FromSeconds(5)))throw new InvalidOperationException("OWNED_STA_BLOCK_EXIT_TIMEOUT");if(callback is not null&&!callback.Wait(TimeSpan.FromSeconds(5)))throw new InvalidOperationException("OWNED_REPLAY_EXIT_TIMEOUT");}
        blocking.GetAwaiter().GetResult();callback!.GetAwaiter().GetResult();
    }
    static void RunMsiReplayCases()
    {
        foreach(var row in ManualModels)
        {
            ReplayCase("msi-replay-original-firmware:"+row.name,backend=>{Check(Invoke(backend,"NotifyMsiFirmwareModeChanged",1L)is true,"New actual firmware revision must arm one replay");Check(MsiManualIoPorts.Rows.Count==0&&MsiReplayIoPorts.Arms.Count==1,"Heartbeat mode observation arms but never writes");MsiReplayIoPorts.Fire();ReplayWritesOnSta(backend);Check(Get(backend,"msiFirmwareModeSettledRevision")is long revision&&revision==1&&Get(ManualSubmission(backend),"Success")is true,"Actual callback settles the same completed firmware revision");},row.product,row.name,row.firmware);
            ReplayCase("msi-replay-original-external-profile:"+row.name,backend=>{EmitApplied(backend,"external-fixture");Check(MsiManualIoPorts.Rows.Count==0&&MsiReplayIoPorts.Arms.Count==1,"Original Applied callback only queues its detached snapshot");MsiReplayIoPorts.Fire();ReplayWritesOnSta(backend);Check(Get(backend,"profileSelectionSource")?.ToString()=="HC.ProfileManager.Applied"&&Get(Get(backend,"externalProfileQueue")!,"HasPendingForSelfTest")is false,"Actual replay consumes current original profile snapshot once");},row.product,row.name,row.firmware);
            ReplayCase("msi-replay-original-power-edge:"+row.name,backend=>{MsiReplayIoPorts.PowerOnline=false;MsiReplayIoPorts.Fire();ReplayWritesOnSta(backend);Check(Get(backend,"profilePowerLineOnline")is false&&Get(ManualSubmission(backend),"Success")is true,"Power edge replay consumes live profile context and actual original fan results");},row.product,row.name,row.firmware);
        }
        ReplayCase("msi-replay-original-old-timer-after-command",backend=>{var old=MsiReplayIoPorts.LatestId;Check(Invoke(backend,"NotifyMsiFirmwareModeChanged",1L)is true,"Old timer has an actual pending mode edge");ApplyManual(backend,ManualNodes((0,50),(30,50),(70,70),(100,100)));MsiManualIoPorts.Rows.Clear();MsiReplayIoPorts.Fire(old);Check(MsiManualIoPorts.Rows.Count==0,"Retired timer callback cannot adopt a newer manual control owner");MsiReplayIoPorts.Fire();ReplayWritesOnSta(backend);Check(Get(backend,"msiFirmwareModeSettledRevision")is long version&&version==1,"Current timer still consumes the pending mode edge");});
        ReplayCase("msi-replay-original-old-timer-after-reopen",backend=>{var old=MsiReplayIoPorts.LatestId;ClosePublic(backend);OpenPublic(backend);Invoke(backend,"OpenEvents");Invoke(backend,"AllowWritesAfterResume");ApplyManual(backend);MsiManualIoPorts.Rows.Clear();Invoke(backend,"NotifyMsiFirmwareModeChanged",1L);MsiReplayIoPorts.Fire(old);Check(MsiManualIoPorts.Rows.Count==0,"A callback queued before Close cannot adopt the reopened device/control lifetime");MsiReplayIoPorts.Fire();ReplayWritesOnSta(backend);});
        ReplayCase("msi-replay-original-discard-waits-applied",backend=>{var callback=ProfileDelegates("Discarded");callback.DynamicInvoke(ReplayProfile(backend,"discarded-fixture"),false);MsiReplayIoPorts.Fire();Check(MsiManualIoPorts.Rows.Count==0&&MsiReplayIoPorts.Arms.Count==2&&MsiReplayIoPorts.Arms.Last().Due>0,"Original discard consumes one edge and arms only its bounded deadline, without synthesizing a curve");EmitApplied(backend,"next-original-profile");MsiReplayIoPorts.Fire();ReplayWritesOnSta(backend);Check(Get(backend,"profileSelectionSource")?.ToString()=="HC.ProfileManager.Applied","Only the subsequent current Applied event completes handoff");});
        ReplayCase("msi-replay-original-old-profile-generation",backend=>{var handler=ProfileDelegates("Applied");var profile=ReplayProfile(backend,"old-original-profile");var source=Enum.Parse(Hc!.GetType("HandheldCompanion.UpdateSource",true)!,"QuickProfilesPage");ClosePublic(backend);OpenPublic(backend);Invoke(backend,"OpenEvents");Invoke(backend,"AllowWritesAfterResume");ApplyManual(backend);MsiManualIoPorts.Rows.Clear();MsiReplayIoPorts.Arms.Clear();handler.DynamicInvoke(profile,source);MsiReplayIoPorts.Fire();Check(MsiManualIoPorts.Rows.Count==0&&MsiReplayIoPorts.Arms.Count==0,"Original detached event delegate from an older session cannot queue or replay into reopened ownership");});
        ReplayCase("msi-replay-original-sleep-blocks-callback",backend=>{Invoke(backend,"NotifyMsiFirmwareModeChanged",1L);Set(backend,"suspendGateEpoch",1L);MsiReplayIoPorts.Fire();Check(MsiManualIoPorts.Rows.Count==0,"New sleep epoch blocks actual queued callback before its original writers");});
        ReplayCase("msi-replay-original-close-blocks-callback",backend=>{Invoke(backend,"NotifyMsiFirmwareModeChanged",1L);ClosePublic(backend);MsiManualIoPorts.Rows.Clear();MsiReplayIoPorts.Fire();Check(MsiManualIoPorts.Rows.Count==0,"A disposed original timer callback after close cannot start a write");});
        ReplayCase("msi-replay-original-mode-duplicate-and-coalesce",backend=>{Check(Invoke(backend,"NotifyMsiFirmwareModeChanged",2L)is true&&Invoke(backend,"NotifyMsiFirmwareModeChanged",1L)is false&&Invoke(backend,"NotifyMsiFirmwareModeChanged",2L)is false&&Invoke(backend,"NotifyMsiFirmwareModeChanged",3L)is true,"Original monotonic mode edge accepts new revisions and rejects duplicate/older values");MsiReplayIoPorts.Fire();ReplayWritesOnSta(backend);Check(Get(backend,"msiFirmwareModeSettledRevision")is long version&&version==3,"One current callback settles latest coalesced original mode revision");MsiManualIoPorts.Rows.Clear();MsiReplayIoPorts.Fire();Check(MsiManualIoPorts.Rows.Count==0&&Invoke(backend,"NotifyMsiFirmwareModeChanged",3L)is false,"Completed duplicate notifications cannot create repeated firmware writes");});
        ReplayCase("msi-replay-original-mode-failure-once",backend=>{MsiManualIoPorts.FailedRead="Get_Fan";MsiManualIoPorts.FailedBlock=1;Invoke(backend,"NotifyMsiFirmwareModeChanged",1L);MsiReplayIoPorts.Fire();Check(Get(ManualSubmission(backend),"Success")is false&&Get(backend,"msiFirmwareModeSettledRevision")is long version&&version==1,"Original failed mode revision remains failed yet consumes its one allowed attempt");MsiManualIoPorts.Rows.Clear();MsiReplayIoPorts.Fire();Check(MsiManualIoPorts.Rows.Count==0&&Invoke(backend,"NotifyMsiFirmwareModeChanged",1L)is false,"Failed mode replay cannot fight the OEM writer with unbounded retry");});
        ReplayCase("msi-replay-original-profile-retry-bounded",backend=>{MsiManualIoPorts.FailedRead="Get_Fan";MsiManualIoPorts.FailedBlock=1;EmitApplied(backend,"failure-original-profile");for(var attempt=0;attempt<3;attempt++)MsiReplayIoPorts.Fire();var queue=Get(backend,"externalProfileQueue")!;Check(Get(queue,"HasPendingForSelfTest")is false&&MsiReplayIoPorts.Arms.Count==3&&MsiReplayIoPorts.Arms.Skip(1).All(r=>r.Due==2000),"Actual profile write failures consume exactly three original attempts and two bounded retry arms");MsiManualIoPorts.Rows.Clear();MsiReplayIoPorts.Fire();Check(MsiManualIoPorts.Rows.Count==0,"Exhausted original profile snapshot cannot be replayed again");});
        ReplayCase("msi-replay-original-new-applied-during-write",backend=>{EmitApplied(backend,"first-original-profile");MsiManualIoPorts.OnIo=row=>{if(row.Stage=="write"&&row.Index==1){MsiManualIoPorts.OnIo=null;EmitApplied(backend,"new-original-profile");}};MsiReplayIoPorts.Fire();Check(Get(Get(backend,"externalProfileQueue")!,"HasPendingForSelfTest")is true,"An earlier replay cannot complete a newer real Applied snapshot");MsiManualIoPorts.Rows.Clear();MsiReplayIoPorts.Fire();ReplayWritesOnSta(backend);Check(Get(Get(backend,"externalProfileQueue")!,"HasPendingForSelfTest")is false&&Get(backend,"profileSelectionSource")?.ToString()=="HC.ProfileManager.Applied","Next callback consumes only the latest current profile snapshot");});
        ReplayCase("msi-replay-original-queued-owner-replaced",backend=>{EmitApplied(backend,"queued-old-original-profile");ReplayWaitsForOriginalSta(backend,()=>{ApplyManual(backend,ManualNodes((0,50),(30,50),(70,70),(100,100)));MsiManualIoPorts.Rows.Clear();},()=>{});Check(MsiManualIoPorts.Rows.Count==0,"A callback admitted before STA wait cannot adopt the command that replaced its captured curve while it waited");});
        ReplayCase("msi-replay-original-queued-sleep-announcement",backend=>{EmitApplied(backend,"queued-before-sleep");ReplayWaitsForOriginalSta(backend,()=>{},()=>Invoke(backend,"BlockWritesForSuspend"));Check(MsiManualIoPorts.Rows.Count==0,"The original queued callback retains its pre-sleep epoch rather than recapturing a wake/close generation");});
        ReplayCase("msi-replay-original-no-pending-no-rearm",backend=>{var count=MsiReplayIoPorts.Arms.Count;for(var i=0;i<3;i++)MsiReplayIoPorts.Fire();Check(MsiManualIoPorts.Rows.Count==0&&MsiReplayIoPorts.Arms.Count==count,"No mode/profile/power edge produces no writes and no new one-shot arms");});
        ReplayCase("msi-replay-original-manual-fullspeed-replayed",backend=>{ApplyManual(backend,ManualNodes((0,100),(30,100),(70,100),(100,100)));MsiManualIoPorts.Rows.Clear();MsiReplayIoPorts.Arms.Clear();Invoke(backend,"NotifyMsiFirmwareModeChanged",1L);MsiReplayIoPorts.Fire();ReplayWritesOnSta(backend);Check(Get(ManualSubmission(backend),"FullSpeedRequested")is true&&(MsiLifecycleIoPorts.Full&0x80)!=0,"Actual mode replay preserves the current explicit full-speed user intent");});
    }
}
